def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(write_time, current_time):
        return current_time >= write_time + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            keys_to_remove = [k for k in cache if is_expired(cache[k][1], t)]
            for k in keys_to_remove:
                del cache[k]

            # If key exists, remove it to re-add it at the end
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is new, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove first item (LRU)

            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            keys_to_remove = [k for k in cache if is_expired(cache[k][1], t)]
            for k in keys_to_remove:
                del cache[k]

            if key in cache:
                value, write_time = cache[key]
                results.append(value)
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
            else:
                results.append(-1)

    return results

